using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check which projects actually compiled vs which were skipped
var targets = build.FindChildrenRecursive<Target>();
foreach (var t in targets.Where(x => x.Name == "CoreCompile"))
{
    var proj = t.GetNearestParent<Project>()?.Name ?? "unknown";
    Console.WriteLine($"CoreCompile ran in: {proj}");
}

Console.WriteLine();

