var allErrors = build.FindChildrenRecursive<Error>();
Console.WriteLine($"Total errors: {allErrors.Count()}");
foreach (var e in allErrors)
{
    var proj = e.GetNearestParent<Project>()?.Name ?? "unknown";
    Console.WriteLine($"[{proj}] {e.Code}: {e.Text}");
}
